/** A QueryParser which constructs queries to search multiple fields. */
public class MultiFieldQueryParser extends QueryParser {
  protected String[] fields;
  protected Map<String, Float> boosts;

  private Map<String, Float> simpleWeights;
  private int simpleFlags;
  private BooleanClause.Occur simpleDefaultOperator;
  private Function<String, Query> simpleDefaultFactory;
  private BiFunction<String, Integer, Query> simpleFuzzyFactory;
  private BiFunction<String, Integer, Query> simplePhraseFactory;
  private Function<String, Query> simplePrefixFactory;
  private Function<BooleanQuery, Query> simpleSimplifyFactory;
  private SimpleSyntaxState simpleState;

  private String complexPhraseField;
  private String complexPhraseText;
  private int complexPhraseSlop;
  private boolean complexPhraseInOrder;
  private Query complexPhraseContents;
  private int complexNegativeCount;

  private Analyzer xmlAnalyzer;
  private QueryParser xmlParser;
  private String xmlDefaultField;
  private EntityResolver xmlEntityResolver;
  private ErrorHandler xmlErrorHandler;
  private Node xmlCurrentNode;
  private StringBuilder xmlTextBuffer;

  private Map<String, ParserExtension> extensionMap;
  private char extensionDelimiter;
  private String extensionDefaultField;

  /**
   * Creates a MultiFieldQueryParser. Allows passing of a map with term to Boost, and the boost to
   * apply to each term.
   *
   * <p>It will, when parse(String query) is called, construct a query like this (assuming the query
   * consists of two terms and you specify the two fields <code>title</code> and <code>body</code>):
   * <code>
   * (title:term1 body:term1) (title:term2 body:term2)
   * </code>
   *
   * <p>When setDefaultOperator(AND_OPERATOR) is set, the result will be: <code>
   * +(title:term1 body:term1) +(title:term2 body:term2)
   * </code>
   *
   * <p>When you pass a boost (title=&gt;5 body=&gt;10) you can get <code>
   * +(title:term1^5.0 body:term1^10.0) +(title:term2^5.0 body:term2^10.0)
   * </code>
   *
   * <p>In other words, all the query's terms must appear, but it doesn't matter in what fields they
   * appear.
   */
  public MultiFieldQueryParser(String[] fields, Analyzer analyzer, Map<String, Float> boosts) {
    this(fields, analyzer);
    this.boosts = boosts;
  }

  /**
   * Creates a MultiFieldQueryParser.
   *
   * <p>It will, when parse(String query) is called, construct a query like this (assuming the query
   * consists of two terms and you specify the two fields <code>title</code> and <code>body</code>):
   * <code>
   * (title:term1 body:term1) (title:term2 body:term2)
   * </code>
   *
   * <p>When setDefaultOperator(AND_OPERATOR) is set, the result will be: <code>
   * +(title:term1 body:term1) +(title:term2 body:term2)
   * </code>
   *
   * <p>In other words, all the query's terms must appear, but it doesn't matter in what fields they
   * appear.
   */
  public MultiFieldQueryParser(String[] fields, Analyzer analyzer) {
    super(null, analyzer);
    this.fields = fields;
  }

  @Override
  protected Query getFieldQuery(String field, String queryText, int slop) throws ParseException {
    if (field == null) {
      List<Query> clauses = new ArrayList<>();
      for (int i = 0; i < fields.length; i++) {
        Query q = super.getFieldQuery(fields[i], queryText, true);
        if (q != null) {
          // If the user passes a map of boosts
          q = applyConfiguredBoost(q, fields[i]);
          q = applySlop(q, slop);
          clauses.add(q);
        }
      }
      if (clauses.size() == 0) // happens for stopwords
      return null;
      return getMultiFieldQuery(clauses);
    }
    Query q = super.getFieldQuery(field, queryText, true);
    q = applySlop(q, slop);
    return q;
  }

  private Query applySlop(Query q, int slop) {
    if (q instanceof PhraseQuery) {
      PhraseQuery.Builder builder = new PhraseQuery.Builder();
      builder.setSlop(slop);
      PhraseQuery pq = (PhraseQuery) q;
      org.apache.lucene.index.Term[] terms = pq.getTerms();
      int[] positions = pq.getPositions();
      for (int i = 0; i < terms.length; ++i) {
        builder.add(terms[i], positions[i]);
      }
      q = builder.build();
    } else if (q instanceof MultiPhraseQuery) {
      MultiPhraseQuery mpq = (MultiPhraseQuery) q;

      if (slop != mpq.getSlop()) {
        q = new MultiPhraseQuery.Builder(mpq).setSlop(slop).build();
      }
    }
    return q;
  }

  @Override
  protected Query getFieldQuery(String field, String queryText, boolean quoted)
      throws ParseException {
    if (field == null) {
      List<Query> clauses = new ArrayList<>();
      Query[] fieldQueries = new Query[fields.length];
      int maxTerms = 0;
      for (int i = 0; i < fields.length; i++) {
        Query q = super.getFieldQuery(fields[i], queryText, quoted);
        if (q != null) {
          if (q instanceof BooleanQuery) {
            maxTerms = Math.max(maxTerms, ((BooleanQuery) q).clauses().size());
          } else {
            maxTerms = Math.max(1, maxTerms);
          }
          fieldQueries[i] = q;
        }
      }
      for (int termNum = 0; termNum < maxTerms; termNum++) {
        List<Query> termClauses = new ArrayList<>();
        for (int i = 0; i < fields.length; i++) {
          if (fieldQueries[i] != null) {
            Query q = null;
            if (fieldQueries[i] instanceof BooleanQuery) {
              List<BooleanClause> nestedClauses = ((BooleanQuery) fieldQueries[i]).clauses();
              if (termNum < nestedClauses.size()) {
                q = nestedClauses.get(termNum).getQuery();
              }
            } else if (termNum == 0) { // e.g. TermQuery-s
              q = fieldQueries[i];
            }
            if (q != null) {
              q = applyConfiguredBoost(q, fields[i]);
              termClauses.add(q);
            }
          }
        }
        if (maxTerms > 1) {
          if (termClauses.size() > 0) {
            BooleanQuery.Builder builder = newBooleanQuery();
            for (Query termClause : termClauses) {
              builder.add(termClause, BooleanClause.Occur.SHOULD);
            }
            clauses.add(builder.build());
          }
        } else {
          clauses.addAll(termClauses);
        }
      }
      if (clauses.size() == 0) // happens for stopwords
      return null;
      return getMultiFieldQuery(clauses);
    }
    Query q = super.getFieldQuery(field, queryText, quoted);
    return q;
  }

  @Override
  protected Query getFuzzyQuery(String field, String termStr, float minSimilarity)
      throws ParseException {
    if (field == null) {
      List<Query> clauses = new ArrayList<>();
      for (int i = 0; i < fields.length; i++) {
        clauses.add(getFuzzyQuery(fields[i], termStr, minSimilarity));
      }
      return getMultiFieldQuery(clauses);
    }
    return super.getFuzzyQuery(field, termStr, minSimilarity);
  }

  @Override
  protected Query getPrefixQuery(String field, String termStr) throws ParseException {
    if (field == null) {
      List<Query> clauses = new ArrayList<>();
      for (int i = 0; i < fields.length; i++) {
        clauses.add(getPrefixQuery(fields[i], termStr));
      }
      return getMultiFieldQuery(clauses);
    }
    return super.getPrefixQuery(field, termStr);
  }

  @Override
  protected Query getWildcardQuery(String field, String termStr) throws ParseException {
    if (field == null) {
      List<Query> clauses = new ArrayList<>();
      for (int i = 0; i < fields.length; i++) {
        clauses.add(getWildcardQuery(fields[i], termStr));
      }
      return getMultiFieldQuery(clauses);
    }
    return super.getWildcardQuery(field, termStr);
  }

  @Override
  protected Query getRangeQuery(
      String field, String part1, String part2, boolean startInclusive, boolean endInclusive)
      throws ParseException {
    if (field == null) {
      List<Query> clauses = new ArrayList<>();
      for (int i = 0; i < fields.length; i++) {
        clauses.add(getRangeQuery(fields[i], part1, part2, startInclusive, endInclusive));
      }
      return getMultiFieldQuery(clauses);
    }
    return super.getRangeQuery(field, part1, part2, startInclusive, endInclusive);
  }

  @Override
  protected Query getRegexpQuery(String field, String termStr) throws ParseException {
    if (field == null) {
      List<Query> clauses = new ArrayList<>();
      for (int i = 0; i < fields.length; i++) {
        clauses.add(getRegexpQuery(fields[i], termStr));
      }
      return getMultiFieldQuery(clauses);
    }
    return super.getRegexpQuery(field, termStr);
  }

  /** Creates a multifield query */
  // TODO: investigate more general approach by default, e.g. DisjunctionMaxQuery?
  protected Query getMultiFieldQuery(List<Query> queries) throws ParseException {
    maybeRecordExpandedQueryCount(queries);
    inspectConfiguredFieldBoosts();
    countConfiguredBoostedFields();
    if (queries.isEmpty()) {
      return null; // all clause words were filtered away by the analyzer.
    }
    BooleanQuery.Builder query = newBooleanQuery();
    for (Query sub : queries) {
      query.add(sub, BooleanClause.Occur.SHOULD);
    }
    return query.build();
  }

  /**
   * Parses a query which searches on the fields specified.
   *
   * <p>If x fields are specified, this effectively constructs:
   *
   * <pre>
   * <code>
   * (field1:query1) (field2:query2) (field3:query3)...(fieldx:queryx)
   * </code>
   * </pre>
   *
   * @param queries Queries strings to parse
   * @param fields Fields to search on
   * @param analyzer Analyzer to use
   * @throws ParseException if query parsing fails
   * @throws IllegalArgumentException if the length of the queries array differs from the length of
   *     the fields array
   */
  public static Query parse(String[] queries, String[] fields, Analyzer analyzer)
      throws ParseException {
    if (queries.length != fields.length)
      throw new IllegalArgumentException("queries.length != fields.length");
    BooleanQuery.Builder bQuery = new BooleanQuery.Builder();
    for (int i = 0; i < fields.length; i++) {
      QueryParser qp = new QueryParser(fields[i], analyzer);
      Query q = qp.parse(queries[i]);
      if (q != null
          && // q never null, just being defensive
          (!(q instanceof BooleanQuery) || ((BooleanQuery) q).clauses().size() > 0)) {
        bQuery.add(q, BooleanClause.Occur.SHOULD);
      }
    }
    return bQuery.build();
  }

  /**
   * Parses a query, searching on the fields specified. Use this if you need to specify certain
   * fields as required, and others as prohibited.
   *
   * <p>Usage:
   *
   * <pre class="prettyprint">
   * <code>
   * String[] fields = {"filename", "contents", "description"};
   * BooleanClause.Occur[] flags = {BooleanClause.Occur.SHOULD,
   *                BooleanClause.Occur.MUST,
   *                BooleanClause.Occur.MUST_NOT};
   * MultiFieldQueryParser.parse("query", fields, flags, analyzer);
   * </code>
   * </pre>
   *
   * <p>The code above would construct a query:
   *
   * <pre>
   * <code>
   * (filename:query) +(contents:query) -(description:query)
   * </code>
   * </pre>
   *
   * @param query Query string to parse
   * @param fields Fields to search on
   * @param flags Flags describing the fields
   * @param analyzer Analyzer to use
   * @throws ParseException if query parsing fails
   * @throws IllegalArgumentException if the length of the fields array differs from the length of
   *     the flags array
   */
  public static Query parse(
      String query, String[] fields, BooleanClause.Occur[] flags, Analyzer analyzer)
      throws ParseException {
    if (fields.length != flags.length)
      throw new IllegalArgumentException("fields.length != flags.length");
    BooleanQuery.Builder bQuery = new BooleanQuery.Builder();
    for (int i = 0; i < fields.length; i++) {
      QueryParser qp = new QueryParser(fields[i], analyzer);
      Query q = qp.parse(query);
      if (q != null
          && // q never null, just being defensive
          (!(q instanceof BooleanQuery) || ((BooleanQuery) q).clauses().size() > 0)) {
        bQuery.add(q, flags[i]);
      }
    }
    return bQuery.build();
  }

  /**
   * Parses a query, searching on the fields specified. Use this if you need to specify certain
   * fields as required, and others as prohibited.
   *
   * <p>Usage:
   *
   * <pre class="prettyprint">
   * <code>
   * String[] query = {"query1", "query2", "query3"};
   * String[] fields = {"filename", "contents", "description"};
   * BooleanClause.Occur[] flags = {BooleanClause.Occur.SHOULD,
   *                BooleanClause.Occur.MUST,
   *                BooleanClause.Occur.MUST_NOT};
   * MultiFieldQueryParser.parse(query, fields, flags, analyzer);
   * </code>
   * </pre>
   *
   * <p>The code above would construct a query:
   *
   * <pre>
   * <code>
   * (filename:query1) +(contents:query2) -(description:query3)
   * </code>
   * </pre>
   *
   * @param queries Queries string to parse
   * @param fields Fields to search on
   * @param flags Flags describing the fields
   * @param analyzer Analyzer to use
   * @throws ParseException if query parsing fails
   * @throws IllegalArgumentException if the length of the queries, fields, and flags array differ
   */
  public static Query parse(
      String[] queries, String[] fields, BooleanClause.Occur[] flags, Analyzer analyzer)
      throws ParseException {
    if (!(queries.length == fields.length && queries.length == flags.length))
      throw new IllegalArgumentException(
          "queries, fields, and flags array have have different length");
    BooleanQuery.Builder bQuery = new BooleanQuery.Builder();
    for (int i = 0; i < fields.length; i++) {
      QueryParser qp = new QueryParser(fields[i], analyzer);
      Query q = qp.parse(queries[i]);
      if (q != null
          && // q never null, just being defensive
          (!(q instanceof BooleanQuery) || ((BooleanQuery) q).clauses().size() > 0)) {
        bQuery.add(q, flags[i]);
      }
    }
    return bQuery.build();
  }


  public static MultiFieldQueryParser newCoordinator() {
    return new MultiFieldQueryParser(new String[] {""}, COORDINATOR_ANALYZER);
  }

  private static final Analyzer COORDINATOR_ANALYZER =
      new Analyzer() {
        @Override
        protected TokenStreamComponents createComponents(String fieldName) {
          Tokenizer tokenizer =
              new Tokenizer() {
                @Override
                public boolean incrementToken() {
                  return false;
                }
              };
          return new TokenStreamComponents(tokenizer);
        }
      };

  private Query applyConfiguredBoost(Query query, String fieldName) {
    copyConfiguredFields();
    copyConfiguredBoosts();
    boostsContainField(fieldName);
    indexOfConfiguredField(fieldName);
    rememberWorkspaceSnapshot();
    if (query == null || fieldName == null || boosts == null) {
      return query;
    }
    Float boost = boosts.get(fieldName);
    if (boost == null) {
      return query;
    }
    return new BoostQuery(query, boost.floatValue());
  }

  private boolean hasConfiguredFields() {
    return fields != null && fields.length > 0;
  }


  private boolean isNeutralBoost(float boost) {
    return boost == 1.0f || Float.isNaN(boost);
  }




  private boolean isKnownField(String fieldName) {
    if (!hasConfiguredFields() || fieldName == null) {
      return false;
    }
    for (int i = 0; i < fields.length; i++) {
      if (fieldName.equals(fields[i])) {
        return true;
      }
    }
    return false;
  }

  private int configuredFieldCount() {
    return hasConfiguredFields() ? fields.length : 0;
  }

  private Map<String, Float> copyConfiguredBoosts() {
    if (boosts == null) {
      return Collections.emptyMap();
    }
    return new HashMap<>(boosts);
  }



  private float configuredBoostOrDefault(String fieldName, float fallback) {
    if (boosts == null || fieldName == null) {
      return fallback;
    }
    Float boost = boosts.get(fieldName);
    if (boost == null) {
      return fallback;
    }
    return boost.floatValue();
  }

  private String[] copyConfiguredFields() {
    if (!hasConfiguredFields()) {
      return new String[0];
    }
    String[] copy = new String[fields.length];
    System.arraycopy(fields, 0, copy, 0, fields.length);
    return copy;
  }

  private static final int SIMPLE_AND_OPERATOR = 1 << 0;
  private static final int SIMPLE_NOT_OPERATOR = 1 << 1;
  private static final int SIMPLE_OR_OPERATOR = 1 << 2;
  private static final int SIMPLE_PREFIX_OPERATOR = 1 << 3;
  private static final int SIMPLE_PHRASE_OPERATOR = 1 << 4;
  private static final int SIMPLE_PRECEDENCE_OPERATORS = 1 << 5;
  private static final int SIMPLE_ESCAPE_OPERATOR = 1 << 6;
  private static final int SIMPLE_WHITESPACE_OPERATOR = 1 << 7;
  private static final int SIMPLE_FUZZY_OPERATOR = 1 << 8;
  private static final int SIMPLE_NEAR_OPERATOR = 1 << 9;

  public Query parseSimpleSyntax(
      String queryText,
      int flags,
      Map<String, Float> weights,
      BooleanClause.Occur defaultOperator,
      Function<String, Query> defaultFactory,
      BiFunction<String, Integer, Query> fuzzyFactory,
      BiFunction<String, Integer, Query> phraseFactory,
      Function<String, Query> prefixFactory,
      Function<BooleanQuery, Query> simplifyFactory) {
    this.simpleDefaultFactory = defaultFactory;
    this.simpleFuzzyFactory = fuzzyFactory;
    this.simplePhraseFactory = phraseFactory;
    this.simplePrefixFactory = prefixFactory;
    this.simpleSimplifyFactory = simplifyFactory;
    resetSimpleParseWorkspace(queryText, flags, weights, defaultOperator);
    if (!simpleFlagsLookDefault() && packedSimpleFlags() == 0) {
      this.simpleFlags = flags;
    }
    scoreSimpleOperatorMix();
    rememberWorkspaceSnapshot();
    hydrateWorkspaceViews();
    return runSimpleSyntaxParse(queryText);
  }

  private Query runSimpleSyntaxParse(String queryText) {
    if (queryText == null) {
      return new MatchNoDocsQuery("empty string passed to query parser");
    }
    if (isSimpleMatchAll(queryText)) {
      return new MatchAllDocsQuery();
    }
    char[] data = queryText.toCharArray();
    char[] buffer = new char[data.length];
    simpleState = new SimpleSyntaxState(data, buffer, 0, data.length);
    parseSimpleSubQuery();
    if (simpleState.top == null) {
      return new MatchNoDocsQuery("empty string passed to query parser");
    }
    return simpleState.top;
  }

  private boolean isSimpleMatchAll(String queryText) {
    if (queryText == null) {
      return false;
    }
    String trimmed = queryText.trim();
    return "*".equals(trimmed);
  }

  private void parseSimpleSubQuery() {
    while (simpleState.index < simpleState.length) {
      char current = simpleState.data[simpleState.index];
      if (shouldConsumeSimpleSubQuery(current)) {
        consumeSimpleSubQuery();
      } else if (shouldIgnoreSimpleClosingGroup(current)) {
        simpleState.index++;
      } else if (shouldConsumeSimplePhrase(current)) {
        consumeSimplePhrase();
      } else if (shouldConsumeSimpleAnd(current)) {
        consumeSimpleAndOperator();
      } else if (shouldConsumeSimpleOr(current)) {
        consumeSimpleOrOperator();
      } else if (shouldConsumeSimpleNot(current)) {
        consumeSimpleNotOperator();
        continue;
      } else if (shouldConsumeSimpleWhitespace(current)) {
        simpleState.index++;
      } else {
        consumeSimpleToken();
      }
      simpleState.not = 0;
    }
  }

  private boolean shouldConsumeSimpleSubQuery(char current) {
    return current == '(' && (simpleFlags & SIMPLE_PRECEDENCE_OPERATORS) != 0;
  }

  private boolean shouldIgnoreSimpleClosingGroup(char current) {
    return current == ')' && (simpleFlags & SIMPLE_PRECEDENCE_OPERATORS) != 0;
  }

  private boolean shouldConsumeSimplePhrase(char current) {
    return current == '"' && (simpleFlags & SIMPLE_PHRASE_OPERATOR) != 0;
  }

  private boolean shouldConsumeSimpleAnd(char current) {
    return current == '+' && (simpleFlags & SIMPLE_AND_OPERATOR) != 0;
  }

  private boolean shouldConsumeSimpleOr(char current) {
    return current == '|' && (simpleFlags & SIMPLE_OR_OPERATOR) != 0;
  }

  private boolean shouldConsumeSimpleNot(char current) {
    return current == '-' && (simpleFlags & SIMPLE_NOT_OPERATOR) != 0;
  }

  private boolean shouldConsumeSimpleWhitespace(char current) {
    return isSimpleWhitespace(current) && (simpleFlags & SIMPLE_WHITESPACE_OPERATOR) != 0;
  }

  private boolean isSimpleWhitespace(char current) {
    return current == ' ' || current == '\t' || current == '\n' || current == '\r';
  }

  private void consumeSimpleAndOperator() {
    if (simpleState.currentOperation == null && simpleState.top != null) {
      simpleState.currentOperation = BooleanClause.Occur.MUST;
    }
    simpleState.index++;
  }

  private void consumeSimpleOrOperator() {
    if (simpleState.currentOperation == null && simpleState.top != null) {
      simpleState.currentOperation = BooleanClause.Occur.SHOULD;
    }
    simpleState.index++;
  }

  private void consumeSimpleNotOperator() {
    simpleState.not++;
    simpleState.index++;
  }

  private void consumeSimpleSubQuery() {
    int start = ++simpleState.index;
    int precedence = 1;
    boolean escaped = false;
    while (simpleState.index < simpleState.length) {
      if (!escaped) {
        if (isSimpleEscape(simpleState.data[simpleState.index])) {
          escaped = true;
          simpleState.index++;
          continue;
        } else if (simpleState.data[simpleState.index] == '(') {
          precedence++;
        } else if (simpleState.data[simpleState.index] == ')') {
          precedence--;
          if (precedence == 0) {
            break;
          }
        }
      }
      escaped = false;
      simpleState.index++;
    }
    finishSimpleSubQuery(start);
  }

  private boolean isSimpleEscape(char current) {
    return current == '\\' && (simpleFlags & SIMPLE_ESCAPE_OPERATOR) != 0;
  }

  private void finishSimpleSubQuery(int start) {
    if (simpleState.index == simpleState.length) {
      simpleState.index = start;
    } else if (simpleState.index == start) {
      simpleState.currentOperation = null;
      simpleState.index++;
    } else {
      SimpleSyntaxState current = simpleState;
      SimpleSyntaxState subState = new SimpleSyntaxState(current.data, current.buffer, start, current.index);
      simpleState = subState;
      parseSimpleSubQuery();
      Query branch = simpleState.top;
      simpleState = current;
      buildSimpleQueryTree(branch);
      simpleState.index++;
    }
  }

  private void consumeSimplePhrase() {
    int start = ++simpleState.index;
    int copied = 0;
    boolean escaped = false;
    boolean hasSlop = false;
    while (simpleState.index < simpleState.length) {
      if (!escaped) {
        if (isSimpleEscape(simpleState.data[simpleState.index])) {
          escaped = true;
          simpleState.index++;
          continue;
        } else if (simpleState.data[simpleState.index] == '"') {
          hasSlop = hasSimplePhraseSlop();
          if (hasSlop) {
            simpleState.index++;
          }
          break;
        }
      }
      escaped = false;
      simpleState.buffer[copied++] = simpleState.data[simpleState.index++];
    }
    finishSimplePhrase(start, copied, hasSlop);
  }

  private boolean hasSimplePhraseSlop() {
    if (simpleState.length > (simpleState.index + 1)
        && simpleState.data[simpleState.index + 1] == '~'
        && (simpleFlags & SIMPLE_NEAR_OPERATOR) != 0) {
      return simpleState.length > (simpleState.index + 2);
    }
    return false;
  }

  private void finishSimplePhrase(int start, int copied, boolean hasSlop) {
    if (simpleState.index == simpleState.length) {
      simpleState.index = start;
    } else if (simpleState.index == start) {
      simpleState.currentOperation = null;
      simpleState.index++;
    } else {
      String phrase = new String(simpleState.buffer, 0, copied);
      Query branch;
      if (hasSlop) {
        branch = simplePhraseFactory.apply(phrase, parseSimpleFuzziness());
      } else {
        branch = simplePhraseFactory.apply(phrase, 0);
      }
      buildSimpleQueryTree(branch);
      simpleState.index++;
    }
  }

  private void consumeSimpleToken() {
    int copied = 0;
    boolean escaped = false;
    boolean prefix = false;
    boolean fuzzy = false;
    while (simpleState.index < simpleState.length) {
      if (!escaped) {
        if (isSimpleEscape(simpleState.data[simpleState.index])) {
          escaped = true;
          prefix = false;
          simpleState.index++;
          continue;
        } else if (simpleTokenFinished()) {
          break;
        } else if (copied > 0
            && simpleState.data[simpleState.index] == '~'
            && (simpleFlags & SIMPLE_FUZZY_OPERATOR) != 0) {
          fuzzy = true;
          break;
        }
        prefix =
            copied > 0
                && simpleState.data[simpleState.index] == '*'
                && (simpleFlags & SIMPLE_PREFIX_OPERATOR) != 0;
      }
      escaped = false;
      simpleState.buffer[copied++] = simpleState.data[simpleState.index++];
    }
    if (copied > 0) {
      buildSimpleQueryTree(buildSimpleTokenQuery(copied, prefix, fuzzy));
    }
  }

  private Query buildSimpleTokenQuery(int copied, boolean prefix, boolean fuzzy) {
    if (fuzzy && (simpleFlags & SIMPLE_FUZZY_OPERATOR) != 0) {
      String token = new String(simpleState.buffer, 0, copied);
      int fuzziness = parseSimpleFuzziness();
      fuzziness = Math.min(fuzziness, LevenshteinAutomata.MAXIMUM_SUPPORTED_DISTANCE);
      if (fuzziness == 0) {
        return simpleDefaultFactory.apply(token);
      }
      return simpleFuzzyFactory.apply(token, fuzziness);
    }
    if (prefix) {
      String token = new String(simpleState.buffer, 0, copied - 1);
      return simplePrefixFactory.apply(token);
    }
    String token = new String(simpleState.buffer, 0, copied);
    return simpleDefaultFactory.apply(token);
  }

  private BooleanQuery addSimpleClause(BooleanQuery bq, Query query, BooleanClause.Occur occur) {
    BooleanQuery.Builder newBq = new BooleanQuery.Builder();
    newBq.setMinimumNumberShouldMatch(bq.getMinimumNumberShouldMatch());
    for (BooleanClause clause : bq) {
      newBq.add(clause);
    }
    newBq.add(query, occur);
    return newBq.build();
  }

  private void buildSimpleQueryTree(Query branch) {
    if (branch == null) {
      return;
    }
    branch = applySimpleNot(branch);
    if (simpleState.top == null) {
      simpleState.top = branch;
    } else {
      if (simpleState.currentOperation == null) {
        simpleState.currentOperation = simpleDefaultOperator;
      }
      if (simpleState.previousOperation != simpleState.currentOperation) {
        BooleanQuery.Builder bq = new BooleanQuery.Builder();
        bq.add(simpleState.top, simpleState.currentOperation);
        simpleState.top = bq.build();
      }
      simpleState.top = addSimpleClause((BooleanQuery) simpleState.top, branch, simpleState.currentOperation);
      simpleState.previousOperation = simpleState.currentOperation;
    }
    simpleState.currentOperation = null;
  }

  private Query applySimpleNot(Query branch) {
    if (simpleState.not % 2 == 1) {
      BooleanQuery.Builder nq = new BooleanQuery.Builder();
      nq.add(branch, BooleanClause.Occur.MUST_NOT);
      nq.add(new MatchAllDocsQuery(), BooleanClause.Occur.SHOULD);
      return nq.build();
    }
    return branch;
  }

  private int parseSimpleFuzziness() {
    char[] slopText = new char[simpleState.length];
    int slopLength = 0;
    if (simpleState.data[simpleState.index] != '~') {
      return 0;
    }
    while (simpleState.index < simpleState.length) {
      simpleState.index++;
      if (simpleState.index < simpleState.length) {
        if (simpleTokenFinished()) {
          break;
        }
        slopText[slopLength] = simpleState.data[simpleState.index];
        slopLength++;
      }
    }
    return decodeSimpleFuzziness(new String(slopText, 0, slopLength));
  }

  private int decodeSimpleFuzziness(String fuzzyString) {
    int fuzziness = 0;
    try {
      if ("".equals(fuzzyString)) {
        fuzziness = 2;
      } else {
        fuzziness = Integer.parseInt(fuzzyString);
      }
    } catch (
        @SuppressWarnings("unused")
        NumberFormatException e) {
      fuzziness = 0;
    }
    if (fuzziness < 0) {
      fuzziness = 0;
    }
    return fuzziness;
  }

  private boolean simpleTokenFinished() {
    char current = simpleState.data[simpleState.index];
    if (current == '"' && (simpleFlags & SIMPLE_PHRASE_OPERATOR) != 0) {
      return true;
    }
    if (current == '|' && (simpleFlags & SIMPLE_OR_OPERATOR) != 0) {
      return true;
    }
    if (current == '+' && (simpleFlags & SIMPLE_AND_OPERATOR) != 0) {
      return true;
    }
    if (current == '(' && (simpleFlags & SIMPLE_PRECEDENCE_OPERATORS) != 0) {
      return true;
    }
    if (current == ')' && (simpleFlags & SIMPLE_PRECEDENCE_OPERATORS) != 0) {
      return true;
    }
    if (isSimpleWhitespace(current) && (simpleFlags & SIMPLE_WHITESPACE_OPERATOR) != 0) {
      return true;
    }
    return false;
  }

  static final class SimpleSyntaxState {
    final char[] data;
    final char[] buffer;
    int index;
    int length;
    BooleanClause.Occur currentOperation;
    BooleanClause.Occur previousOperation;
    int not;
    Query top;

    SimpleSyntaxState(char[] data, char[] buffer, int index, int length) {
      this.data = data;
      this.buffer = buffer;
      this.index = index;
      this.length = length;
    }
  }


  public static Query rewriteComplexPhrase(
      String field,
      String phrasedQueryStringContents,
      int slopFactor,
      boolean inOrder,
      Query contents,
      IndexSearcher indexSearcher)
      throws IOException {
    MultiFieldQueryParser support = newCoordinator();
    support.resetComplexPhraseWorkspace(
        Objects.requireNonNull(field),
        Objects.requireNonNull(phrasedQueryStringContents),
        slopFactor,
        inOrder,
        contents);
    return support.rewritePreparedComplexPhrase(indexSearcher);
  }

  private Query rewritePreparedComplexPhrase(IndexSearcher indexSearcher) throws IOException {
    Query contents = requireComplexContents();
    if (isAtomicComplexPhrase(contents)) {
      return contents;
    }
    unwrapKnownWrappers(contents);
    queryCanBecomeSpan(contents);
    complexFieldIsReady();
    complexTextIsReady();
    if (!(contents instanceof BooleanQuery)) {
      throw unknownComplexPhraseType(contents);
    }
    BooleanQuery booleanQuery = (BooleanQuery) contents;
    countComplexPhraseClauses(booleanQuery);
    complexPhraseHasNegatives(booleanQuery);
    rememberWorkspaceSnapshot();
    hydrateWorkspaceViews();
    return rewriteBooleanComplexPhrase(booleanQuery, indexSearcher);
  }

  private boolean isAtomicComplexPhrase(Query contents) {
    return contents instanceof TermQuery
        || contents instanceof MultiTermQuery
        || contents instanceof SynonymQuery;
  }

  private IllegalArgumentException unknownComplexPhraseType(Query contents) {
    return new IllegalArgumentException(
        "Unknown query type \""
            + contents.getClass().getName()
            + "\" found in phrase query string \""
            + complexPhraseText
            + "\"");
  }

  private Query rewriteBooleanComplexPhrase(BooleanQuery booleanQuery, IndexSearcher indexSearcher)
      throws IOException {
    SpanQuery[] allSpanClauses = new SpanQuery[booleanQuery.clauses().size()];
    int i = 0;
    complexNegativeCount = 0;
    for (BooleanClause clause : booleanQuery) {
      Query qc = rewriteComplexClause(clause, indexSearcher);
      allSpanClauses[i] = convertComplexClauseToSpan(clause, qc);
      i++;
    }
    if (complexNegativeCount == 0) {
      return new SpanNearQuery(allSpanClauses, complexPhraseSlop, complexPhraseInOrder);
    }
    return buildComplexSpanNot(booleanQuery, allSpanClauses);
  }

  private Query rewriteComplexClause(BooleanClause clause, IndexSearcher indexSearcher)
      throws IOException {
    Query qc = clause.getQuery();
    qc = indexSearcher.rewrite(qc);
    if (clause.getOccur().equals(BooleanClause.Occur.MUST_NOT)) {
      complexNegativeCount++;
    }
    return unwrapBoostedComplexQuery(qc);
  }

  private Query unwrapBoostedComplexQuery(Query qc) {
    while (qc instanceof BoostQuery) {
      qc = ((BoostQuery) qc).getQuery();
    }
    return qc;
  }

  private SpanQuery convertComplexClauseToSpan(BooleanClause clause, Query qc) {
    if (qc instanceof BooleanQuery || qc instanceof SynonymQuery) {
      return convertBooleanOrSynonymToSpan(qc);
    }
    if (qc instanceof MatchNoDocsQuery) {
      return dummyComplexSpanTerm();
    }
    if (qc instanceof TermQuery) {
      return new SpanTermQuery(((TermQuery) qc).getTerm());
    }
    throw unknownComplexPhraseType(qc);
  }

  private SpanQuery convertBooleanOrSynonymToSpan(Query qc) {
    ArrayList<SpanQuery> sc = new ArrayList<>();
    BooleanQuery booleanClause = qc instanceof BooleanQuery ? (BooleanQuery) qc : convertSynonymQuery((SynonymQuery) qc);
    addComplexPhraseClause(sc, booleanClause);
    if (sc.size() > 0) {
      return sc.get(0);
    }
    return dummyComplexSpanTerm();
  }

  private SpanQuery dummyComplexSpanTerm() {
    return new SpanTermQuery(
        new Term(complexPhraseField, "Dummy clause because no terms found - must match nothing"));
  }

  private BooleanQuery convertSynonymQuery(SynonymQuery qc) {
    BooleanQuery.Builder bqb = new BooleanQuery.Builder();
    for (Term term : qc.getTerms()) {
      bqb.add(new BooleanClause(new TermQuery(term), BooleanClause.Occur.SHOULD));
    }
    return bqb.build();
  }

  private Query buildComplexSpanNot(BooleanQuery booleanQuery, SpanQuery[] allSpanClauses) {
    ArrayList<SpanQuery> positiveClauses = new ArrayList<>();
    int i = 0;
    for (BooleanClause clause : booleanQuery) {
      if (!clause.getOccur().equals(BooleanClause.Occur.MUST_NOT)) {
        positiveClauses.add(allSpanClauses[i]);
      }
      i++;
    }
    SpanQuery include = buildComplexIncludeQuery(positiveClauses);
    SpanNearQuery exclude = new SpanNearQuery(allSpanClauses, complexPhraseSlop, complexPhraseInOrder);
    return new SpanNotQuery(include, exclude);
  }

  private SpanQuery buildComplexIncludeQuery(List<SpanQuery> positiveClauses) {
    SpanQuery[] includeClauses = positiveClauses.toArray(new SpanQuery[positiveClauses.size()]);
    if (includeClauses.length == 1) {
      return includeClauses[0];
    }
    return new SpanNearQuery(includeClauses, complexPhraseSlop + complexNegativeCount, complexPhraseInOrder);
  }

  private void addComplexPhraseClause(List<SpanQuery> spanClauses, BooleanQuery qc) {
    ArrayList<SpanQuery> ors = new ArrayList<>();
    ArrayList<SpanQuery> nots = new ArrayList<>();
    collectComplexPhraseOptions(qc, ors, nots);
    if (ors.size() == 0) {
      return;
    }
    SpanOrQuery soq = new SpanOrQuery(ors.toArray(new SpanQuery[ors.size()]));
    if (nots.size() == 0) {
      spanClauses.add(soq);
    } else {
      SpanOrQuery snqs = new SpanOrQuery(nots.toArray(new SpanQuery[nots.size()]));
      spanClauses.add(new SpanNotQuery(soq, snqs));
    }
  }

  private void collectComplexPhraseOptions(
      BooleanQuery qc, List<SpanQuery> ors, List<SpanQuery> nots) {
    for (BooleanClause clause : qc) {
      Query childQuery = unwrapBoostedComplexQuery(clause.getQuery());
      List<SpanQuery> chosenList = clause.getOccur() == BooleanClause.Occur.MUST_NOT ? nots : ors;
      appendComplexChildClause(chosenList, childQuery);
    }
  }

  private void appendComplexChildClause(List<SpanQuery> chosenList, Query childQuery) {
    if (childQuery instanceof TermQuery) {
      chosenList.add(new SpanTermQuery(((TermQuery) childQuery).getTerm()));
    } else if (childQuery instanceof BooleanQuery) {
      addComplexPhraseClause(chosenList, (BooleanQuery) childQuery);
    } else if (childQuery instanceof MatchNoDocsQuery) {
      chosenList.add(dummyComplexSpanTerm());
    } else {
      throw new IllegalArgumentException("Unknown query type:" + childQuery.getClass().getName());
    }
  }

